INSERT INTO post (id, slug, title, excerpt, content, tags, published_at, status, scheduled_at, author_id) VALUES (1, '欢迎来到marublog', '欢迎来到MaruBlog！', '这是一篇欢迎文章', '很高兴撑到了MaruBlog上线的一天！虽然暂时还没什么功能，不过能想到什么就开发什么吧！ 下面贴个图庆祝一下： ![图片](/api/uploads/1764511009166-9bhtmxpkv2e.jpg) ', '[]', '2025-11-30 13:57:14.89', 'published', NULL, 1);
INSERT INTO post (id, slug, title, excerpt, content, tags, published_at, status, scheduled_at, author_id) VALUES (41, '学习一下游戏音乐的编法', '学习一下游戏音乐的编法', '真的是这样吗？', '今天看了希望与梦想之地的走带，发现其实每个pattern都很简洁，所以学习一下这样写会不会没那么乱？ 这里主要将的是片段尽量简洁然后把他们堆在一起的方法，至于递进式地往里加纯粹是在做实验删除其他变量导致的。 [audio:随便写个递进看看.ogg](/api/uploads/1782568457143-v9ab2d2px7d.ogg) 听上去很特别，但我还是觉得没解决乱的问题……', '["音乐"]', '2026-06-27 13:55:28.087', 'published', NULL, 1);
INSERT INTO post (id, slug, title, excerpt, content, tags, published_at, status, scheduled_at, author_id) VALUES (2, '关于icp备案的吐槽', '关于ICP备案的吐槽', '我只能说真的很麻烦……吐血牢求镇楼。', ' ![图片](/api/uploads/1764655554765-lmh0d53as49.png) # ICP备案真的很麻烦 首先第一个网页我打算稳当点走大陆内服务器，于是为了让域名解析到这个网页，我必须进行ICP备案。 本来备案过程顺顺利利，直到系统发现我证件跟定位不同，非要我出居住证明的时候，我懵了。 一只去外省读书的🐖，怎么证明它住在学校里。 于是翻来翻去，先是上网搜，没有说的；又是问导员，导员又说学校的开具基本没有效力…… #### 啊，额刚收到新消息……这样吗。唉，后面再吧……（flag1） 这怎么办，没办法啊又回去服务器文档那边看看。终于给我找到，我这地方必须得上传居住证和暂住证。 证怎么来呢？去pcs办呗。然而刚要打电话发现人家刚下班1分钟…… 这可怎么办啊…… 想着先在网上登记一下，就去网上填表了。大不了挑个近一点的pcs办这个证—— 然后……然后就是flag1了。 flag1：在码字的过程中，网上办事给我发消息了，办理结果显示： ### 驳回申请，本地办不了居住证 ### …… ## What the f—— #####（🐷脑过载重启中……） 心情复杂，伤心在备案的漫漫长路依旧未完，唯一一丝慰藉应该是不用去pcs办东西了吧。（哭哭） ……唉，就这样吧，后续想着去供应商发个工单看看能交什么证明应该是最现实的选择。 # 最后…… 今天贴一手最近刚写的纯音乐吧，回望自己那么久的编曲历程，感觉进步微乎及微的。有的时候我会质疑我走过的路，因为从我身边跑过的人的背影想当然会撑大我的阴暗面。于是停在原地想，坚持的路数如果不对了，还会有所收获吗？还是说现在，我只是在不安中否定曾经的自己？无论怎么说，目前为止没有放弃依旧是最为正确的选项。因为这种思维只是一瞬的犹豫（我大概不适合emo :P），又怎么抵得过几年来的辛苦和喜悦。 到这吧，我还是不擅长写这种。多的不说，这首用了最近刚翻出来的羽管键琴音色，因为听到的时候第一反应就是：“这不是，魔女吗！”就照着这种意象做了。鼓组随便找了个好听的amen break切的，然而切出来其实差强人意（倒不如说什么都差强人意……）总之这首没写完但最近为这个ICP搞得晕头转向的……（竟然圆回来了） 祝你听的不算难过，嘻嘻。 <div className="card" data-audio> <div>🎵 majocombat.ogg</div> <audio controls src="/api/uploads/1764657598030-gmn58d1s9xj.ogg" preload="none" style={{width:''100%''}} /> </div> ', '[]', '2025-12-02 06:40:20.912', 'published', NULL, 1);
