INSERT INTO post (id, slug, title, excerpt, content, tags, published_at, status, scheduled_at, author_id) VALUES (44, '竟然一个月没发', '竟然一个月没发……', '倒不如说网站n个月没更新？', '我说别吵再不学点混口饭吃的，像我这种东学西学啥也不会的就要完蛋了（ 最近在看点JDBC和javaweb（快速过了都多少看过一些），话说代码块识别什么时候上线啊（我说真的时间紧迫，这种真得鸽子吧）。', '["科技"]', '2026-09-12 02:32:20.378', 'published', NULL, 1);
INSERT INTO post (id, slug, title, excerpt, content, tags, published_at, status, scheduled_at, author_id) VALUES (8, 'afwgaergrhagagrgsrsasf', 'AFWGAERGRHAGAGRGSRSASF', 'AGDRGAHAHFDGAR', '**_` ``` # - [文本](链接)![alt](地址) ``` `_** ![图片](/api/uploads/1764685563122-j9zwhxtbn1.png) <div className="card" data-audio> <div>🎵 DJAshin - 黑大婶回乡带娃-苹果香 （DJ百大菌Remix）.mp3</div> <audio controls src="/api/uploads/1764685626233-x1hk6x769j.mp3" preload="none" style={{width:''100%''}} /> </div> ', '["编程","音乐","绘画","科技","生活","闲谈","其他"]', '2025-12-02 14:26:10.392', 'draft', '2025-12-02 14:28:00', 10);
