INSERT INTO post (id, slug, title, excerpt, content, tags, published_at, status, scheduled_at, author_id) VALUES (22, '嗯op', '嗯……OP', '真的是op', '照着op的感觉做了！听完一遍突然觉得…… ### 这bass的沙比律动不会写真的很难听 ### 不过至少确立一个主旋律之后就可以像zun和toby一样偷懒复用吧！（大嘘） 反正后续应该还会重置，目前就写个能听的程度试试！其他比如画画和写作也还远着呢，该不会真就磨蹭一辈子来产出这个作品吧T_T！ <div className="card" data-audio> <div>🎵 Opening Song(Game Edit.).ogg</div> <audio controls src="/api/uploads/1770387838769-i6rra8aygvj.ogg" preload="none" style={{width:''100%''}} /> </div> ### 题外话…… ### 立绘很久没有得到翻新的捷琳belike: ![图片](/api/uploads/1770388140193-sdsxqt8k4af.jpg) 也该重新拿起笔画画了呢（拿的起来吗，存疑） ## 2.8 曲目更新 ## 这次完成度更高了！所以又想发布一次！总的来说干了以下几个事情： 给bass加了点律动（虽然我觉得听着还有些谔谔，但至少比以前全部音黏在一起要好！） ②给能ott得ott了，我认为最明显的是钢琴的瞬态明亮了不少，bass的话也象征性地装了……收效甚微！（要不是管弦插件暂时没研究出来怎么拉条线出来，我早就想给每个乐器塞个ott来压缩一下了！） ④eq了一小部分乐器…… 目前虽然感觉有进步，但发现了很多新的问题 ①就是从各个乐器糊糊的时代转到现在，发现主歌部分……真的在打架，这真的怪我当时一直在给每个乐器乱写……真就无端堆砌，可是现在又懒得改（总得改的吧？） ②bass真的是……第一版就一直在说bass律动跟史一样，结果打开工程发现并没写律动，现在加上之后看上去不是黏在一块的巨史，而是变成未经修饰但却被切成臊子的碎史屑。看来bass律动的学习任重道远啊！ ③其他真没改，真不会改（比如电吉需不需要区分一下，给管弦插件拉出几个通道对每个管弦乐器插效果器什么的……这些全 都 不 会 做~） <div className="card" data-audio> <div>🎵 Opening Song(Game Edit.).ogg</div> <audio controls src="/api/uploads/1770485328663-iinv1wr4cbr.ogg" preload="none" style={{width:''100%''}} /> </div> 总之请听吧！我努力肘击这首op也很久了！快20个小时？！！还是从25年3月开始写的！谔谔。如果后面学到点新的修改方法，肘到30小时或许不是问题呢！缝缝补补又一年啊—— ![图片](/api/uploads/1770485456929-dnr6ne4ijnh.jpg) ', '["音乐","绘画"]', '2026-02-06 14:29:27.81', 'published', NULL, 1);
INSERT INTO post (id, slug, title, excerpt, content, tags, published_at, status, scheduled_at, author_id) VALUES (38, '音乐随笔', '音乐随笔~', '纯粹地消磨时间', ' [audio:随便写写2.ogg](/api/uploads/1779433177462-x4j2k9iht17.ogg) 头一次见有音乐随笔的，虽然配器还是有点乱但确实听感还行吧。 如果我有cutie mark，我认为可能是奥塔维亚的音符标记了（个人马设吗有趣），因为我学不明白现代电子音乐，感觉上手还是经典乐器容易些。还有尽管作品并没有多好听，但实际上目前比较肯花时间的地方就在音乐了，你说的对吧画画和剧本人格（？）。 阿b不发预告，但是有张崔克西快画完了（吗？），我说手里的豆包视频从5.4开始都攥烂了6月才发。', '["音乐"]', '2026-05-22 07:04:59.166', 'published', NULL, 1);
INSERT INTO post (id, slug, title, excerpt, content, tags, published_at, status, scheduled_at, author_id) VALUES (12, '测试一下上传大图片并查看sharp模块运行情况', '测试一下上传大图片并查看sharp模块运行情况', '这图……5mb大小', ' ![图片](/api/uploads/1764850087595-h47kajke74.jpg) 2024年2月的时候打通了莱莎1呢，不过莱莎2就没打完了哈哈，只记得系统和优化相对一代来讲都相当烂……', '["编程"]', '2025-12-04 12:08:55.974', 'published', NULL, 1);
INSERT INTO post (id, slug, title, excerpt, content, tags, published_at, status, scheduled_at, author_id) VALUES (15, '也是尝试在学校电脑上登录这个网站了', '也是尝试在学校电脑上登录这个网站了', '看看有什么好发上来的', '# 正在严肃备战CET-6和嵌入式stm32！ ## 其实嘴上说着没事心里压力大概不小…… 如果可以随手考过就好了！ 下面都是偷的学校电脑里的内容，看看怎么样！ ![图片](/api/uploads/1765433610316-9zhqxpoxloj.jpg) <div className="card" data-audio> <div>🎵 Sleep Away.mp3</div> <audio controls src="/api/uploads/1765433635628-9qwg9fl4cpl.mp3" preload="none" style={{width:''100%''}} /> </div> ', '[]', '2025-12-11 06:14:19.058', 'published', NULL, 4);
INSERT INTO post (id, slug, title, excerpt, content, tags, published_at, status, scheduled_at, author_id) VALUES (25, '在用户这边发个新的曲子', '在用户这边发个新的曲子', 'I have two sides......', '** 我有小号（确信）** <div className="card" data-audio> <div>🎵 Ending Song(？).ogg</div> <audio controls src="/api/uploads/1773304591036-1pvg6xg1df4.ogg" preload="none" style={{width:''100%''}} /> </div> 没有特意做减法，只是尽力压低了乐器的独立表现。或许没有op听着乱了，但肯定比op无聊 :P 你说的对吧，bass。 下面是加强了一下小号的声音……其他不想说了。 也不知道要不要再加长一点，但我感觉ed没那么长用不到？ 电脑里有一个op ed写了但其他一点进度都没有的项目……不过写歌真好玩，总有一天会意识到画画编程也好玩吧（然后到时候又觉得编曲不好玩了，热度是这样的）。 ## 更新一下…… [audio:Ending Song(Game Edit 2).ogg](/api/uploads/1776600031696-d90ja1i7kuw.ogg) ', '["音乐"]', '2026-03-12 08:37:23.824', 'published', NULL, 4);
INSERT INTO post (id, slug, title, excerpt, content, tags, published_at, status, scheduled_at, author_id) VALUES (37, 'my-little-pony', 'My Little Pony~', '记录一下小马绘画，第一幅是蝶神！', '![图片](/api/uploads/1777782615378-d9nxja8lz4e.jpg) # 蝶神美如画！渣画技都掩盖不了的美丽~ 细节先发自己网站 **宣告主权**（乐）可以注意一下发布时间，大概是5/3 12点左右。（后面又修改了一下不知道会不会改时间） 可能发布的其他平台包括（因为还没发）：p站，b站，崔站。 可能的简介： 新手可以爱记录，可以乱打草稿，可以放弃技术乱画，可以磨洋工慢慢画。但就是不能敢署名！（？） 没有模仿官风的意思，但是照着官风简洁的画法画了！以后应该会重置或者新画一幅，毕竟蝶神值得（？） 没有预告！但以后基本只画pony了，肘击灵长类动物失败是这样的，怎么画人这么难，不过如果是EQG或许可以试试（？） 才发现有点搞，崔站贴的p站的地址，p站藏了个人主页到这里，有人能查到这里来我吃（', '["绘画"]', '2026-05-03 04:39:43.662', 'published', NULL, 1);
INSERT INTO post (id, slug, title, excerpt, content, tags, published_at, status, scheduled_at, author_id) VALUES (40, '更新一下随笔2', '更新一下随笔2', '认真的调整和弦和旋律让他们听起来和谐！', ' [audio:随便写写2.ogg](/api/uploads/1780890714140-p85q45upd3r.ogg) 看到toby也经常用套路和弦恍然大悟，原来歌好不好听其实跟套路没有关系…… 目前忠于听感调整，配器方面还行没几个但或许没以前乱（但还是有些乱……） 崔真的快画完了别催o(╥﹏╥)o ![图片](/api/uploads/1780890869303-tjt4t4mstjh.jpg) ', '["音乐","闲谈","绘画"]', '2026-06-08 03:54:31.995', 'published', NULL, 1);
INSERT INTO post (id, slug, title, excerpt, content, tags, published_at, status, scheduled_at, author_id) VALUES (43, '玩个吉他先', '玩个吉他先', '副歌2摆了', '如副标题所示，乱得要死，懒得改了，有机会再改 [audio:belongs2.ogg](/api/uploads/1786939422455-5g3kc1dtq8m.ogg) # 几天前改了 [audio:belongs2.ogg](/api/uploads/1789179857571-ymjph5u3dd8.ogg) ', '["音乐"]', '2026-08-17 04:03:43.777', 'published', NULL, 1);
INSERT INTO post (id, slug, title, excerpt, content, tags, published_at, status, scheduled_at, author_id) VALUES (45, '跟ai请教一下快乐核', '跟ai请教一下快乐核', '成品出来把自己笑死了', '这个音色设计确实完全平淡，而且实际上编排也没好好排（写到后面绷不住了不想排了）不过确实学到了很多理论上的东西吧……暂时不想接着钻研了？（反正差不多病好了又得回去学习别的。） [audio:Hapicorn.ogg](/api/uploads/1790771000770-a1efc5lqdk6.ogg) 很粗制滥造的一曲！但是感觉学到点东西了，所以自然是开心的。', '["音乐"]', '2026-09-30 12:24:57.678', 'published', NULL, 1);
INSERT INTO post (id, slug, title, excerpt, content, tags, published_at, status, scheduled_at, author_id) VALUES (17, '这是个草稿啊', '这是个草稿啊', '有没有人懂草稿的', ' ## 问题出在？ ## 真不容易啊，搞半天（准确来说是14天）发现是没反代业务端口，额……总之反代完后就可以正常访问本站啦！ ## 有什么想说 ## 站点几乎是最小可运行版本！后续还会添加全局音乐播放和更好的动画效果！（这取决于什么时候给我的codex续费……哈哈。）暂时可以当个日记本用了，如果有其他博友在用，还请不要天天视煎窝qwq，我心理活动很多。 ## 就要就要 ## 那我也没办法，但我想如果博友没那么冒犯，我当然会发更多爆的……但如果一直被困扰，我就只会当做日常吹水地了啊！其实要求不过是别真实我就好了…… ## 实际上就只有自己用的话 ## 当我没说……我大概率真没那个勇气把网站发给别人:P（自私这一块） ## 今天要分享的是…… ## 依旧是没写完的歌，话说我多久没写歌了啊？感觉摸到很瓶颈的地方了，就是写什么怎么听都感觉不够饱满，我猜测是音频填充的问题，但是我又不知道拿什么来填充……额，凑合着听吧。想着之前听过的旮旯曲写的，这个oboe叫啥，双簧管吗？总之很悠扬很好听，爽写完旋律后发现……即使目前各个频段都还很空，也不知道要填入什么！于是晾着了……希望尽早写完！ ## 不过目前在做的事…… ## 嵌入式STM32复习！明天就考感觉得挂！六级也考完了感觉也得挂！（寄） ', '[]', '2025-12-20 03:41:35.134', 'draft', NULL, 1);
