INSERT INTO post (id, slug, title, excerpt, content, tags, published_at, status, scheduled_at, author_id) VALUES (23, '什么也没挂', '什么也没挂！', '是的，就是考了试，什么也没挂。仅此而已。', '难说，万一六级没过线呢，做题做得给到拉完。现在可算有点时间接着做点好玩的了。 ![图片](/api/uploads/1770489523533-ahkxy7qn36r.jpg) ', '["闲谈"]', '2026-02-07 18:39:14.506', 'published', NULL, 1);
INSERT INTO post (id, slug, title, excerpt, content, tags, published_at, status, scheduled_at, author_id) VALUES (21, '更新一下歌曲', '更新一下歌曲！', '又更了多少……', '只是单纯的增加了Rhodes Piano这一轨chord吧。但是确实没有想到还能增加什么配器！要不再切到别的项目放置一下试试……:P <div className="card" data-audio> <div>🎵 peace.ogg</div> <audio controls src="/api/uploads/1767773067508-ojpkkc19dg.ogg" preload="none" style={{width:''100%''}} /> </div> ', '["音乐"]', '2026-01-07 08:04:31.353', 'published', NULL, 1);
INSERT INTO post (id, slug, title, excerpt, content, tags, published_at, status, scheduled_at, author_id) VALUES (24, '还是打算启动了黄油捏人法', '还是打算启动了黄油捏人法！', '这个投绘画区是何意啊……', '**出恋活静态图初体验belike** 尽管捏了两三天的人，肘击半天动作和滤镜。但似乎还是比画画快呢！至于说效果，我只能说不像大佬能做出自己的风格的话，就会总是一股恋活味啊！不过无所谓，搞来玩玩的！（也难说会不会哪来替换游戏立绘，我又不会画画） ![图片](/api/uploads/1771757653666-x518acst02.jpg) **关于音频：** 这小段音频是之前圣诞的时候，想着过圣诞不写点圣诞氛围的歌？结果整出个莫名其妙的玩意，一点也不圣诞好吧！不过感觉用来做什么小转场（比如要选择的时候放）的音乐就合适了lololol <div className="card" data-audio> <div>🎵 somedaylike.ogg</div> <audio controls src="/api/uploads/1771757788310-36u9w5xlny.ogg" preload="none" style={{width:''100%''}} /> </div> ', '["绘画","科技"]', '2026-02-22 10:56:30.649', 'published', NULL, 1);
