INSERT INTO post (id, slug, title, excerpt, content, tags, published_at, status, scheduled_at, author_id) VALUES (16, '终于终于', '终于……终于！', '网站备案和域名解析工作正式结束！现在可以使用marublog.top访问本站了！', ' ![图片](/api/uploads/1765795289999-dh6yzscec0v.jpg) ## 问题出在？ ## 真不容易啊，搞半天（准确来说是14天）发现是没反代业务端口，额……总之反代完后就可以正常访问本站啦！ ## 有什么想说 ## 站点几乎是最小可运行版本！后续还会添加全局音乐播放和更好的动画效果！（这取决于什么时候给我的codex续费……哈哈。）暂时可以当个日记本用了，如果有其他博友在用，还请不要天天视煎窝qwq，我心理活动很多。 ## 就要就要 ## 那我也没办法，但我想如果博友没那么冒犯，我当然会发更多爆的……但如果一直被困扰，我就只会当做日常吹水地了啊！其实要求不过是别真实我就好了…… ## 实际上就只有自己用的话 ## 当我没说……我大概率真没那个勇气把网站发给别人:P（自私这一块） ## 今天要分享的是…… ## 依旧是没写完的歌，话说我多久没写歌了啊？感觉摸到很瓶颈的地方了，就是写什么怎么听都感觉不够饱满，我猜测是音频填充的问题，但是我又不知道拿什么来填充……额，凑合着听吧。想着之前听过的旮旯曲写的，这个oboe叫啥，双簧管吗？总之很悠扬很好听，爽写完旋律后发现……即使目前各个频段都还很空，也不知道要填入什么！于是晾着了……希望尽早写完！ ## 不过目前在做的事…… ## 嵌入式STM32复习！明天就考感觉得挂！六级也考完了感觉也得挂！（寄） <div className="card" data-audio> <div>🎵 peace.ogg</div> <audio controls src="/api/uploads/1765797045911-umr5rslwgfm.ogg" preload="none" style={{width:''100%''}} /> </div> ## 注意注意！ ## 上面这首有更新（虽然没多写多少！）还请听加了Rhodes Piano的版本！虽然也没听出来和弦配的有多好听，但确实花时间配了！', '[]', '2025-12-15 10:52:18.42', 'published', NULL, 1);
