INSERT INTO post (id, slug, title, excerpt, content, tags, published_at, status, scheduled_at, author_id) VALUES (36, '光速小写个intro', '光速小写个intro……？', NULL, '又回到了混乱塞音色的阶段！不过这一次我挑选了比较干的音色，然后亲自给他们塞混响（？），并且最搞笑的是给所有东西都插上了ott( [audio:12351356真的很好听.ogg](/api/uploads/1776844699015-4qicutp9n1.ogg) 比较想吐槽的点： 小提用的新的插件（其实是旧的，比平常用的edio什么什么的要更音源原始一些）把attack拉到最低还是有很长的前摇……| 又是4536……我说写练习用的和弦乱配就行重点是音色怎么调和正常你二龙（问题是音色还是很凌乱啊……） 前面钢琴的delay也太大太吵了…… 旋律里写的每一个弦外音也太垃圾了……违和感严重就不是自成一派，那叫标新立异…… 比较想吹（然后还会喷一点）的点： 莫名其妙用cello演奏了12351356，我说动机不就来了。（但是大提有点听不见） lofi2插件的pluck很有意思，自己调了调预制调出来的不过太小声了……', '["音乐"]', '2026-04-22 08:02:46.699', 'published', NULL, 1);
INSERT INTO post (id, slug, title, excerpt, content, tags, published_at, status, scheduled_at, author_id) VALUES (35, '可可算修好了tt', '可，可算修好了T_T', '简直是力挽狂澜', ' ![图片](/api/uploads/1776589313115-rsdauqs1pkn.jpg) 目前还要调整一下图片的大小，感觉图片还是太大了，可以把他们限制成……居中然后文章宽度的70%？ ### 关于音频…… [audio:peace.ogg](/api/uploads/1776590369005-fmdezbtbahq.ogg) 又给这个加了点东西，除了最后鼓该怎么写真的没辙了之外暂时没别的感觉。', '[]', '2026-04-19 09:19:46.007', 'published', NULL, 1);
